css:
:root {
  /* Deep Space Voyager Theme - starlit vacuum with cockpit accents */
  --bg-primary: #050608;
  --bg-alt: #0b0f18;
  --bg-alt-rgb: 11, 15, 24;
  --bg-hover: #101725;
  --text-primary: #e3ecff;
  --text-secondary: #9eb6ff;
  --border: #3750a6;
  --border-rgb: 55, 80, 166;
  --accent: #7cf7ff;
  --accent-rgb: 124, 247, 255;
  --accent-hover: #a4fbff;
  --star: rgba(255, 255, 255, 0.9);
}

[data-theme="light"] {
  --bg-primary: #f4f8ff;
  --bg-alt: #e8efff;
  --bg-alt-rgb: 232, 239, 255;
  --bg-hover: #d7e4ff;
  --text-primary: #101725;
  --text-secondary: #3750a6;
  --border: #9eb6ff;
  --border-rgb: 158, 182, 255;
  --accent: #2f9abf;
  --accent-rgb: 47, 154, 191;
  --accent-hover: #3fb5dd;
  --star: rgba(55, 80, 166, 0.8);
}

body {
  background: radial-gradient(circle at 20% 20%, rgba(var(--accent-rgb), 0.1), transparent 25%),
              radial-gradient(circle at 70% 60%, rgba(var(--border-rgb), 0.2), transparent 30%),
              var(--bg-primary);
  color: var(--text-primary);
}

.card {
  background: linear-gradient(145deg, rgba(var(--bg-alt-rgb), 0.9), rgba(5, 6, 8, 0.9));
  border: 1px solid var(--border);
  box-shadow: 0 18px 36px rgba(0, 0, 0, 0.35), 0 0 0 1px rgba(var(--accent-rgb), 0.15);
  position: relative;
  overflow: hidden;
}

.card::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(var(--star) 1px, transparent 1px);
  background-size: 80px 80px;
  opacity: 0.35;
  pointer-events: none;
}

.card-title {
  color: var(--accent);
  letter-spacing: 1.1px;
  text-transform: uppercase;
}
